import urllib.request, urllib.parse, ssl, base64, json

target_ip = '__TARGET_IP__'
target_path = '__TARGET_PATH__'
target_method = '__TARGET_METHOD__'
target_data = '__TARGET_DATA__'

url = f'http://{target_ip}{target_path}' if not target_path.startswith('http') else target_path
if not target_path and not url.endswith('/'):
    url += '/'

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
}

data_bytes = None
if target_data:
    try:
        raw_data = base64.b64decode(target_data).decode('utf-8')
        parsed_data = json.loads(raw_data)
        data_bytes = urllib.parse.urlencode(parsed_data).encode('utf-8')
        headers['Content-Type'] = 'application/x-www-form-urlencoded'
    except Exception:
        pass

html_content = ''
try:
    req = urllib.request.Request(url, data=data_bytes, headers=headers, method=target_method or 'GET')
    with urllib.request.urlopen(req, context=ctx, timeout=12) as response:
        html_content = response.read().decode('utf-8', errors='replace')
except Exception as e1:
    try:
        url_https = f'https://{target_ip}{target_path}' if not target_path.startswith('http') else target_path
        req = urllib.request.Request(url_https, data=data_bytes, headers=headers, method=target_method or 'GET')
        with urllib.request.urlopen(req, context=ctx, timeout=12) as response:
